insert into scolarite.apprenants (
  division_id, type, statut,
  nom, prenom, matricule, grade,
  categorie, code_grade, numero_mecano, sexe,
  date_naissance, situation_matrimoniale, nombre_enfants, nom_pere,
  nom_mere, date_debut_service, date_nomination, date_retraite,
  position_statutaire, service_affectation, emploi_tenu, diplome_militaire,
  diplome_militaire_obtenu_le, diplome_civil, domaine, regie_dorh,
  regie_solde, matricule_solde, unite
)
select
  division.id, 'personnel',
  case when upper(coalesce(etat.unite, 'ENSOA')) = 'ENSOA'
       then 'actif' else 'reverse' end,
  etat.nom, etat.prenom, etat.matricule, etat.grade,
  etat.categorie, etat.code_grade, etat.numero_mecano, etat.sexe,
  etat.date_naissance, etat.situation_matrimoniale, etat.nombre_enfants, etat.nom_pere,
  etat.nom_mere, etat.date_debut_service, etat.date_nomination, etat.date_retraite,
  etat.position_statutaire, etat.service_affectation, etat.emploi_tenu, etat.diplome_militaire,
  etat.diplome_militaire_obtenu_le, etat.diplome_civil, etat.domaine, etat.regie_dorh,
  etat.regie_solde, etat.matricule_solde, etat.unite
from etat, division
on conflict (numero_mecano) where numero_mecano is not null do nothing;

-- ----------------------------------------------------------------------------
-- 3. Contrôle : doit afficher 255 fiches, dont 25 officiers, 172
--    sous-officiers et 58 militaires du rang, 1 reversé — et aucune en
--    formation.
-- ----------------------------------------------------------------------------
select
  count(*) as total,
  count(*) filter (where categorie = 'OFF') as officiers,
  count(*) filter (where categorie = 'SOF') as sous_officiers,
  count(*) filter (where categorie = 'MDR') as militaires_du_rang,
  count(*) filter (where matricule is null) as sans_matricule,
  count(*) filter (where statut = 'reverse') as reverses,
  count(*) filter (where classe_id is not null
                      or promotion_id is not null
                      or section_id is not null) as en_formation
from scolarite.apprenants
where type = 'personnel';
